-- =====================================================================
-- Migration 106: the help desk (tickets, notes, phone alerts, FAQ and guided triage), VenuePlay and PartyPlay
-- ---------------------------------------------------------------------
-- Dean, 19 Oct 2026: "a 'Contact support' form that creates a ticket ... It should be able to do
-- sales, support (venue and customer) and also we could categorise calls as well? Nothing super
-- fancy, just a bit of a report after." And later the same day: "We need to know if it is sales,
-- support, accounts etc enquiry."
--
-- Eight tables, all SERVICE ROLE ONLY. Nothing in a browser reads or writes them directly: the
-- patron form, the venue form, the website contact form, the email path and HQ all go through
-- the billing Worker (venueplay-api), which checks who is asking before it touches a row.
-- PartyPlay's forms post to the same Worker (PartyPlay has its own database, but one desk means
-- one table), marked brand 'partyplay'.
--   - a patron can create a ticket and can never read one back (not even their own)
--   - a venue, a host, a PartyPlay host and a PartyPlay guest can create one and can never read
--     one back, list them or count them, for either brand (Dean, 19 Oct 2026: tickets are for
--     STAFF only)
--   - HQ (vp_platform_admins, role owner, accounts or staff) reads and changes everything
--
-- Branch feature/help-desk. Run BEFORE deploying the billing Worker that goes with it. Either
-- order is safe for a venue night: the help desk is not on any game path, and without these
-- tables the forms answer "we could not send that, email support@venueplay.com.au" instead.
-- After running: python3 venueplay-backend/tools/dump-rls-baseline.py and commit
-- RLS-BASELINE.json (eight new locked tables).
--
-- Safe to run twice. Rollback at the bottom.
-- =====================================================================

begin;

create table if not exists public.vp_help_tickets (
  id              uuid primary key default gen_random_uuid(),
  -- The number a person quotes back to us ("ticket 1042"). Separate from id so nobody ever has
  -- to read a uuid down a phone line.
  ticket_no       bigint generated by default as identity (start with 1001) unique,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  -- One desk for both products (Dean, 19 Oct 2026: "can we dual brand this helpdesk with
  -- partyplay as well?"). Every ticket says which, and HQ filters and reports by it.
  brand           text not null default 'venueplay'
                  check (brand in ('venueplay','partyplay')),
  category        text not null default 'general'
                  check (category in ('sales','venue_support','patron_support','accounts','general')),
  channel         text not null
                  check (channel in ('patron_form','venue_form','web_form','email','phone','manual')),
  status          text not null default 'new'
                  check (status in ('new','open','waiting','closed')),
  priority        text not null default 'normal'
                  check (priority in ('normal','urgent')),
  subject         text not null default '' check (char_length(subject) <= 200),
  message         text not null default '' check (char_length(message) <= 20000),
  contact_name    text check (contact_name is null or char_length(contact_name) <= 120),
  contact_email   text check (contact_email is null or char_length(contact_email) <= 200),
  contact_phone   text check (contact_phone is null or char_length(contact_phone) <= 40),
  -- Which venue it is about. Null for a sales enquiry or an email nobody has matched yet.
  venue_id        uuid references public.vp_venues(id) on delete set null,
  -- The room code the patron was in (for PartyPlay, the party code), and the live session if there was one. No foreign key on
  -- the session: a ticket must outlive the 90-day player-data purge.
  room_code       text check (room_code is null or char_length(room_code) <= 12),
  session_id      uuid,
  -- Who raised it: the venue login (venue form) or the HQ admin (a logged call). Null for a
  -- patron, a website enquiry and an email.
  raised_by       uuid,
  assigned_to     text check (assigned_to is null or char_length(assigned_to) <= 120),
  closed_at       timestamptz,
  -- The email path: which of our addresses it was sent to, and the sender's Message-ID so the
  -- same email delivered twice is one ticket.
  source_address  text check (source_address is null or char_length(source_address) <= 200),
  email_message_id text unique
);

create index if not exists vp_help_tickets_created_idx on public.vp_help_tickets (created_at desc);
create index if not exists vp_help_tickets_status_idx  on public.vp_help_tickets (status, created_at desc);
create index if not exists vp_help_tickets_venue_idx   on public.vp_help_tickets (venue_id, created_at desc);
create index if not exists vp_help_tickets_brand_idx   on public.vp_help_tickets (brand, created_at desc);

create table if not exists public.vp_help_ticket_notes (
  id               uuid primary key default gen_random_uuid(),
  ticket_id        uuid not null references public.vp_help_tickets(id) on delete cascade,
  created_at       timestamptz not null default now(),
  -- note: internal only. reply: an email we sent the contact. email_in: their email back to us.
  -- change: a status, category or priority change, written by HQ so the history is kept.
  kind             text not null default 'note'
                   check (kind in ('note','reply','email_in','change')),
  body             text not null default '' check (char_length(body) <= 20000),
  author           text check (author is null or char_length(author) <= 200),
  author_id        uuid,
  email_message_id text unique
);

create index if not exists vp_help_ticket_notes_ticket_idx on public.vp_help_ticket_notes (ticket_id, created_at);

-- Staff phones and browsers that asked for an alert on a new ticket (Web Push). One row per device.
-- token_hash is the SHA-256 of a secret only that device holds; it is how the device asks what
-- woke it (brand, kind and number, nothing more). filter: every ticket, or only urgent and sales.
create table if not exists public.vp_help_push_subs (
  id            uuid primary key default gen_random_uuid(),
  created_at    timestamptz not null default now(),
  endpoint      text not null unique check (char_length(endpoint) <= 1000),
  filter        text not null default 'all' check (filter in ('all','urgent_sales')),
  auth_user_id  uuid,
  admin_label   text check (admin_label is null or char_length(admin_label) <= 200),
  device_label  text check (device_label is null or char_length(device_label) <= 80),
  token_hash    text not null check (char_length(token_hash) = 64),
  last_peek_at  timestamptz
);

-- ---------------------------------------------------------------------
-- THE HELP CONTENT, edited in HQ (Dean, 19 Oct 2026: "add, edit, reorder, hide questions with no
-- code"). One set per brand and audience: VenuePlay players ('patron') and venues ('venue'),
-- PartyPlay guests ('guest') and hosts ('host'). Seeded below from the FAQ wording Dean approved,
-- plus starter issues for the guided triage.
create table if not exists public.vp_help_faq (
  id          uuid primary key default gen_random_uuid(),
  brand       text not null check (brand in ('venueplay','partyplay')),
  audience    text not null check (audience in ('patron','venue','guest','host')),
  position    int  not null default 0,
  question    text not null check (char_length(question) between 1 and 300),
  answer      text not null check (char_length(answer) between 1 and 3000),
  hidden      boolean not null default false,
  updated_at  timestamptz not null default now(),
  updated_by  text
);
create index if not exists vp_help_faq_set_idx on public.vp_help_faq (brand, audience, position);

-- GUIDED TRIAGE: "What's your issue?", then one step at a time. An issue with no steps goes
-- straight to the contact form. category is what the ticket becomes if the steps do not fix it.
-- auto_order off means the steps stay where HQ put them (Undo of an automatic reorder sets it).
create table if not exists public.vp_help_issues (
  id          uuid primary key default gen_random_uuid(),
  brand       text not null check (brand in ('venueplay','partyplay')),
  audience    text not null check (audience in ('patron','venue','guest','host')),
  position    int  not null default 0,
  title       text not null check (char_length(title) between 1 and 120),
  category    text not null default 'general'
              check (category in ('sales','venue_support','patron_support','accounts','general')),
  hidden      boolean not null default false,
  auto_order  boolean not null default true,
  updated_at  timestamptz not null default now(),
  updated_by  text
);
create index if not exists vp_help_issues_set_idx on public.vp_help_issues (brand, audience, position);

-- One step. tries and fixes count the answers to it ("Fixed it" / "Still not working"); they
-- drive the automatic order (once every unpinned step has about 20) and the flag (under 5% after
-- 30). pinned keeps a step in its place: "Ask the host" stays last, and a step that only makes
-- sense after another stays after it.
create table if not exists public.vp_help_steps (
  id          uuid primary key default gen_random_uuid(),
  issue_id    uuid not null references public.vp_help_issues(id) on delete cascade,
  position    int  not null default 0,
  body        text not null check (char_length(body) between 1 and 300),
  pinned      boolean not null default false,
  hidden      boolean not null default false,
  tries       int  not null default 0,
  fixes       int  not null default 0,
  updated_at  timestamptz not null default now(),
  updated_by  text
);
create index if not exists vp_help_steps_issue_idx on public.vp_help_steps (issue_id, position);

-- Every answer on a Help panel, for the report ("solved without a ticket", and which step fixed
-- it). kind: start (picked an issue), fixed, not_fixed, ticket (went on to the contact form and
-- sent it). Nothing about the person: no device, no address, no message.
create table if not exists public.vp_help_triage_events (
  id          uuid primary key default gen_random_uuid(),
  created_at  timestamptz not null default now(),
  brand       text not null check (brand in ('venueplay','partyplay')),
  issue_id    uuid not null references public.vp_help_issues(id) on delete cascade,
  step_id     uuid references public.vp_help_steps(id) on delete set null,
  kind        text not null check (kind in ('start','fixed','not_fixed','ticket'))
);
create index if not exists vp_help_triage_events_idx on public.vp_help_triage_events (created_at, issue_id);

-- Every automatic reorder, so HQ can see it and undo it.
create table if not exists public.vp_help_reorders (
  id          uuid primary key default gen_random_uuid(),
  created_at  timestamptz not null default now(),
  issue_id    uuid not null references public.vp_help_issues(id) on delete cascade,
  before_ids  jsonb not null,
  after_ids   jsonb not null,
  reason      text,
  undone_at   timestamptz,
  undone_by   text
);
create index if not exists vp_help_reorders_idx on public.vp_help_reorders (created_at desc);

-- LOCKED. Supabase grants anon and authenticated explicitly, so the revoke names them; a revoke
-- FROM public alone reads as a lock and does nothing (migration 32's lesson). No policies are
-- created, so with RLS on and no grants, only the service role (the Worker) can reach a row.
alter table public.vp_help_tickets      enable row level security;
alter table public.vp_help_ticket_notes enable row level security;
alter table public.vp_help_push_subs    enable row level security;
alter table public.vp_help_faq enable row level security;
alter table public.vp_help_issues enable row level security;
alter table public.vp_help_steps enable row level security;
alter table public.vp_help_triage_events enable row level security;
alter table public.vp_help_reorders enable row level security;
revoke all on public.vp_help_tickets      from public, anon, authenticated;
revoke all on public.vp_help_ticket_notes from public, anon, authenticated;
revoke all on public.vp_help_push_subs    from public, anon, authenticated;
revoke all on public.vp_help_faq from public, anon, authenticated;
revoke all on public.vp_help_issues from public, anon, authenticated;
revoke all on public.vp_help_steps from public, anon, authenticated;
revoke all on public.vp_help_triage_events from public, anon, authenticated;
revoke all on public.vp_help_reorders from public, anon, authenticated;
grant select, insert, update, delete on public.vp_help_tickets      to service_role;
grant select, insert, update, delete on public.vp_help_ticket_notes to service_role;
grant select, insert, update, delete on public.vp_help_push_subs    to service_role;
grant select, insert, update, delete on public.vp_help_faq to service_role;
grant select, insert, update, delete on public.vp_help_issues to service_role;
grant select, insert, update, delete on public.vp_help_steps to service_role;
grant select, insert, update, delete on public.vp_help_triage_events to service_role;
grant select, insert, update, delete on public.vp_help_reorders to service_role;

-- THE STARTING CONTENT. FAQ wording as Dean approved it (venueplay/data/help-faq.json and
-- partyplay/data/help-faq.json); starter issues and steps to review in HQ. Fixed ids, so running
-- this file twice adds nothing.
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('056c22db-f321-5856-8033-e70b65d74166', 'venueplay', 'patron', 10, 'How do I join a game?', 'Scan the QR code on the big screen with your phone camera, or go to venueplay.com.au/play and type the 6-character code shown on the screen. There is no app to download and no account to make.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('dda7016a-8b4d-57c8-bf9d-3d3cf3aad46f', 'venueplay', 'patron', 20, 'What name should I use?', 'Any name you like, up to 20 letters. The venue chooses how names show on the big screen, and some show only a first name and an initial. If your name is wrong or you would rather not show it, let the host know.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('0538f842-ef44-52a6-bf55-8ff4a660a2ee', 'venueplay', 'patron', 30, 'My tickets or my game are not showing', 'Your game appears when the host starts it, so if you see "You''re in", you are in and just waiting. If it has started and your phone is still waiting, check the code on your phone matches the big screen, then reload the page. Keep your screen on during the game: some phones pause a page when the screen locks.
In some states bingo is played on paper. If your phone says "Tonight you play on paper", grab a bingo book and mark it off as the numbers are called.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('b52ed834-2e67-56a7-b9e5-19768fafb5f1', 'venueplay', 'patron', 40, 'I have a BINGO. How do I claim it?', 'Press the BINGO button on your phone as soon as your pattern is complete. The host checks it. If you win, show your phone to the host to claim. Prizes are always claimed from the host, never the bar.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('2717ff1f-f6ec-519a-b359-0dc272f36150', 'venueplay', 'patron', 50, 'Who gives out the prizes?', 'The venue. Every prize is offered and given out by the venue running the game. VenuePlay supplies the game software only, so any question about a prize goes to the host or the venue.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('d5534a18-4428-586e-9793-f9acbf9574a1', 'venueplay', 'patron', 60, 'What happens to my details?', 'To play you only need a name. Some venues also ask for an email, a mobile or a postcode, and may ask whether you would like to hear from them; that is always your choice and is never needed to play. Those details belong to the venue. To be taken off a venue''s list, ask the venue or contact us and we will remove you. The full privacy policy is at venueplay.com.au/privacy.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('2ae0fad6-26df-5436-a723-5176fad244b2', 'venueplay', 'patron', 70, 'How do I contact you?', 'Use the form below and we will reply by email, or email support@venueplay.com.au. For anything about tonight''s game or a prize, the host in the room is the quickest help.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('f01b00a1-30fd-5085-a6d1-7542f537714e', 'venueplay', 'venue', 10, 'Getting started', 'Everyone at your venue signs in at venueplay.com.au/app with their mobile number and a code we text them. Pick the game, follow the steps on screen, and players join from their phones with the code on your TV. The guide at venueplay.com.au/training walks through a whole night.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('67840db0-6bea-52b6-81aa-249e2cf977f8', 'venueplay', 'venue', 20, 'Setting up the TV', 'Open your venue''s TV link in the TV''s web browser (or a laptop or streaming stick plugged into the TV) and leave it running. Your TV link is on your Account page. It shows whatever game you start, and your ads between games. If the screen goes blank, reload the page on the TV.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('cf93b70d-90d3-5877-9b97-55d3276726bb', 'venueplay', 'venue', 30, 'Adding hosts and managers', 'On your Account page, choose Add a host and put in their mobile number. They sign in with a text code, so there is no password to share. A host runs games on the night; a manager can also look after your members list, draws, raffles and advertising if you allow it.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('d3a64ff4-0b24-5073-be9a-32f85519ec1b', 'venueplay', 'venue', 40, 'Billing and players', 'Your plan sets how many players can join a night. If a night runs bigger, each extra player is $2 for that night, and your host confirms it on screen before the game starts. Your Account page shows your plan, your next payment and your invoices. For anything about a bill, email accounts@venueplay.com.au.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('5a261283-0033-5c1d-aceb-3baa92eca81f', 'venueplay', 'venue', 50, 'Cancelling', 'The account owner can cancel a venue from the Account page at any time. A monthly plan ends at the end of the current month, and an annual plan runs to the end of the period already paid for.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('774e96e6-3a02-5cd1-b3ec-66dcda83efec', 'venueplay', 'venue', 60, 'Your players'' details', 'Player details collected at your venue belong to your venue. You choose what is collected, and asking for an email or a marketing tick is off until you switch it on. The account owner can download players who opted in. When an account is closed, the details that identify players are deleted within 90 days.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('df7d1acb-f519-5a1a-8889-518c0d69cb87', 'venueplay', 'venue', 70, 'Contacting us', 'Use the form below and we will reply by email. If a game night is going wrong right now, tick "Happening now" so it comes to us marked urgent. You can also email support@venueplay.com.au, or accounts@venueplay.com.au about billing.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('efd4f812-dec9-5f99-9e6a-01fa82ad1dca', 'partyplay', 'guest', 10, 'How do I join the party?', 'Scan the code on the TV with your phone camera, or go to partyplay.com.au/play and type the party code. There is no app, no sign up and no password.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('27135d6d-3a2a-5d76-bbb3-c200ef7c3dcc', 'partyplay', 'guest', 20, 'What name should I use?', 'Any nickname you like. It is the only thing you have to give, and it is how everyone at the party sees you.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('ce0fc5fb-51a7-56aa-ad14-ef226f36388d', 'partyplay', 'guest', 30, 'It says there is no party with that code', 'Check the code against the TV, letter by letter, and try again. If it still will not go, ask your host to check the party screen is open and showing the same code.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('2c916682-7b34-5e78-a80c-3ea7a871ed1e', 'partyplay', 'guest', 40, 'Is this gambling? Do I need to pay?', 'No. PartyPlay is for fun at a private party. Nobody pays to join, there are no entry fees and no tickets to buy, and the games never handle money.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('e3b5edb5-2168-5028-a304-df4b16184153', 'partyplay', 'guest', 50, 'What happens to my details?', 'You give a nickname, and an email only if you want the photo album sent to you. Your nickname, and your email unless you ticked to hear from us, are deleted with the party''s album 30 days after it ends. The full privacy policy is at partyplay.com.au/privacy.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('58323664-cc1f-5674-a77c-c041614745b7', 'partyplay', 'guest', 60, 'How do I contact you?', 'Use the form below and we will reply by email, or email support@partyplay.com.au. For anything about the games tonight, your host is the quickest help.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('4ae2bce7-c77d-5c64-99c0-4212cc4ba563', 'partyplay', 'host', 10, 'How do guests join?', 'Put the party screen on your TV or a laptop. Guests scan the code on it, or type the party code at partyplay.com.au/play, and put in a nickname.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('7b1cffdb-85b5-56b7-a464-321b77198f6b', 'partyplay', 'host', 20, 'How many guests can play?', 'Up to 50. That is the most any party can have, and there is no upgrade beyond it.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('1aaca3c4-2b9a-5270-bafa-53747e92d4e0', 'partyplay', 'host', 30, 'When does my time start?', 'When you press start, not when you pay. A party runs for 24 hours or 3 days, depending on which you bought, and you confirm it on screen first so it cannot start by accident. Building your games beforehand is free and does not start the clock. A licence you never start lapses 12 months after purchase.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('b105fdfe-f001-52df-9c22-b38f160cfa5f', 'partyplay', 'host', 40, 'Is this gambling? Can we play for money?', 'No. PartyPlay is for private parties and the games never handle money: there are no entry fees, no tickets to sell and no cash prizes. A licence used commercially can be ended without a refund.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('589f059f-4d8f-5bf8-a0ff-7e1788781bef', 'partyplay', 'host', 50, 'Refunds and billing', 'Changed your mind within 7 days of buying, before pressing start: full refund. After 7 days, before pressing start: your licence is still there for a year. Once you have pressed start: no refund. For anything about a payment, email accounts@partyplay.com.au.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('c27affec-787b-518e-9663-41f5b34b9877', 'partyplay', 'host', 60, 'Your guests'' details', 'Guests give a nickname, and an email only if they want the photo album. The album, nicknames and emails are deleted 30 days after the party ends. The full privacy policy is at partyplay.com.au/privacy.') on conflict (id) do nothing;
insert into public.vp_help_faq (id, brand, audience, position, question, answer) values ('13eada5b-1c23-5382-aa19-466a67e7cbdd', 'partyplay', 'host', 70, 'Contacting us', 'Use the form below and we will reply by email, or email support@partyplay.com.au.') on conflict (id) do nothing;
insert into public.vp_help_issues (id, brand, audience, position, title, category) values ('72e98832-14f7-5246-963a-3d182327accf', 'venueplay', 'patron', 10, 'My game is not showing', 'patron_support') on conflict (id) do nothing;
insert into public.vp_help_steps (id, issue_id, position, body, pinned) values ('d7307b06-d1f0-5783-8be3-ca3107760225', '72e98832-14f7-5246-963a-3d182327accf', 10, 'Pull down to refresh the page.', false) on conflict (id) do nothing;
insert into public.vp_help_steps (id, issue_id, position, body, pinned) values ('3a4d871c-0aaa-59da-a2ef-f900d9b8b991', '72e98832-14f7-5246-963a-3d182327accf', 20, 'Scan the QR code on the big screen again, so your phone joins the game in this room.', false) on conflict (id) do nothing;
insert into public.vp_help_steps (id, issue_id, position, body, pinned) values ('4299df47-6478-55d7-ba54-1965f7633569', '72e98832-14f7-5246-963a-3d182327accf', 30, 'Check your phone is online: open any other website, or switch between wifi and mobile data.', false) on conflict (id) do nothing;
insert into public.vp_help_steps (id, issue_id, position, body, pinned) values ('33b034ef-4f23-5b15-af96-fba87a982bc0', '72e98832-14f7-5246-963a-3d182327accf', 40, 'Ask the host. They can see who has joined and can get you going.', true) on conflict (id) do nothing;
